L20_1.m_Talk_THA = "คุณได้พูดคำขอหรือไม่? เอ่อ มันก็ไม่มีอะไรร้ายแรงขนาดนั้น"
L20_1.m_Talk_VTN = "cô đã nói một yêu cầu? Ừm, không có gì nghiêm trọng lắm đâu."
L20_1.m_Talk_SCN = "那个……不知道算不算是委托。哈哈，也没那么正式啦。"
L20_1.m_Talk_DEU = "Äh ... kann man das Auftrag nennen? Haha, so formell ist das gar nicht."
L20_1.m_Talk_FRA = "Ah, euh... Une requête ? Ce n'est pas exactement ça, non."
L21_1 = {}
