L21_1.m_CharStrID = "MINT♥WITCH_COUNTERCASE_NULL"
L21_1.m_Talk_KOREA = "제가 이번에 새로운 디저트를 만들었거든요."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "実は私、今回新しいスイーツを開発したんです。"
L21_1.m_Talk_ENG = "You see, I recently made a new dessert recipe."
L21_1.m_Talk_TWN = "我有開發一款新的甜點。"
L21_1.m_Talk_THA = "เห็นไหมว่าฉันเพิ่งทำสูตรขนมใหม่"
L21_1.m_Talk_VTN = "cô thấy đấy, gần đây tôi đã làm một công thức món tráng miệng mới."
L21_1.m_Talk_SCN = "是我这次开发了新的甜点。"
L21_1.m_Talk_DEU = "Ich habe ein neues Dessert kreiert."
L21_1.m_Talk_FRA = "En fait, j'ai créé un nouveau dessert."
L22_1 = {}
