L22_1.m_CharStrID = "MINCHO_BOSS_COUNTERCASE_NULL"
L22_1.m_Talk_KOREA = "아하, 카페에서 일하시는 분이군요. 그래서요?"
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "なるほど、カフェでお仕事されているんですね。続きをお願いできますか？"
L22_1.m_Talk_ENG = "Oh, you work in a cafe? Okay."
L22_1.m_Talk_TWN = "喔～原來你是在咖啡廳工作嗎？那有什麼事嗎？"
L22_1.m_Talk_THA = "โอ้คุณทำงานในร้านกาแฟเหรอ? โอเค"
L22_1.m_Talk_VTN = "Ồ, cô làm việc ở quán cà phê à? Được rồi."
L22_1.m_Talk_SCN = "啊哈，原来是咖啡店的工作人员啊。所以呢？"
L22_1.m_Talk_DEU = "Aha, Sie arbeiten in einem Café, wie ich sehe. Und weiter?"
L22_1.m_Talk_FRA = "Ah je vois. Vous travaillez dans un café, c'est ça ? Je vous écoute."
L23_1 = {}
L23_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_4@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 30914
