L23_1.m_CharStrID = "MINT♥WITCH_COUNTERCASE_NULL"
L23_1.m_Talk_KOREA = "네, 그런데 신메뉴를 개시한지 며칠 되지도 않았는데, 점장이 인기가 없다면서 내리려고 하는 거예요."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "そうです。でも、新メニューを出したばかりなのに、店長に売上が悪いから\n販売終了にすると言われて。"
L23_1.m_Talk_ENG = "It’s only been a few days since we started selling it, but the manager wants to take it off the menu, saying that no one likes it."
L23_1.m_Talk_TWN = "就是，新甜點才開賣沒多久，店長就說賣不好要停賣。"
L23_1.m_Talk_THA = "เพิ่งเริ่มขายได้ไม่กี่วันแต่ผู้จัดการอยากเอาออกจากเมนูบอกว่าไม่มีใครชอบ"
L23_1.m_Talk_VTN = "Chúng tôi mới bắt đầu bán được vài ngày nhưng người quản lý muốn loại nó ra khỏi thực đơn, nói là không ai thích."
L23_1.m_Talk_SCN = "嗯，但新品甜点上市没几天，店长就说因为没有人气要下架。"
L23_1.m_Talk_DEU = "Genau. Aber nur nach einigen Tagen, als wir das Dessert auf das Menü setzten, wollte es unsere Geschäftsführerin wieder streichen, weil es unbeliebt sei."
L23_1.m_Talk_FRA = "En fait, ma patronne m'a demandé de retirer ma création du menu, alors qu'on venait à peine de le lancer !"
