L31_1 = "원래 세상은 선택받은 소수가 다수를 이끌어가는 법이죠."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "この世界は少数の選ばれし者によって多数が導かれています。"
