L30_1.m_Talk_THA = L31_1
L31_1 = "Chỉ có một số ít người được chọn dẫn đầu thế giới."
L30_1.m_Talk_VTN = L31_1
L31_1 = "世界上，本来就是少数的精英在引领多数人。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Die Welt wird verändert durch eine kleine Minderheit der Auserwählten, das war schon immer so."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Que voulez-vous, nous sommes dans un monde où les minorités n'ont d'autre choix que de s'aligner sur la majorité..."
