L35_1 = "역시 민트 초코 좋아하는 사람들끼리는 뭔가 통하는 게 있다니까."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "やっぱりチョコミント好きな仲間同士、通じるものがあるんだわ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "We, the mint chocolate lovers, understand each other."
L34_1.m_Talk_ENG = L35_1
L35_1 = "和喜歡薄荷巧克力的人說起話來真是投機。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "พวกเราคนรักช็อกโกแลตมิ้นต์เข้าใจกัน"
L34_1.m_Talk_THA = L35_1
L35_1 = "Những người yêu thích sôcôla bạc hà chúng ta hiểu nhau mà."
L34_1.m_Talk_VTN = L35_1
L35_1 = "果然喜欢薄荷巧克力的人之间聊天会有共鸣呢。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Menschen, die Minzschoko lieben, verstehen sich eben auf Anhieb!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Entre amateurs de Choco-Menthe, on se comprend."
L34_1.m_Talk_FRA = L35_1
