L36_1.m_CharStrID = "MINCHO_BOSS_COUNTERCASE_NULL"
L37_1 = "아무튼 저희 민초 협회가 뭘 어떻게 도와드리면 될까요?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ところで我々チョウミン協会はどのようにサポートすればよろしいでしょうか？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Anyway, what can we do for you?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "那有什麼是我們超博協會可以幫得上忙的嗎？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "อย่างไรก็ตาม เราทำอะไรให้คุณได้บ้าง?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Dù sao đi nữa, chúng tôi có thể làm gì cho cô?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "那么需要我们薄荷巧克力协会怎么帮你呢？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Jedenfalls – wie können wir Ihnen helfen?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Et que puis-je faire pour vous aider ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "COUNTERCASE_YUNA_NORMAL_4@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 30914
L37_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_StartFXSoundName = "FX_CUTSCEN_BEEP"
L37_1.m_CharStrID = "MINT♥WITCH_COUNTERCASE_NULL"
L38_1 = "사실, 다음주까지 신메뉴가 안 팔리면 메뉴를 내리기로 점장이랑 약속했거든요."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "実は、来週までに新メニューの売り上げが伸びなければメニューから外すって\n店長と約束をしたんです。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "You see, the manager made me promise that I’d remove my dessert from the menu if no one buys it between now and next week."
L37_1.m_Talk_ENG = L38_1
L38_1 = "是這樣的，我和店長打賭，要是到下個禮拜為止，新甜點還是賣不好的話那就下架。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "คุณเห็นไหมว่าผู้จัดการทำให้ฉันสัญญาว่าฉันจะลบของหวานออกจากเมนูถ้าไม่มีใครซื้อระหว่างตอนนี้ถึงสัปดาห์หน้า"
L37_1.m_Talk_THA = L38_1
L38_1 = "cô thấy đấy, người quản lý bắt tôi hứa rằng tôi sẽ loại món tráng miệng của mình khỏi thực đơn nếu không có ai mua nó từ nay đến tuần sau."
L37_1.m_Talk_VTN = L38_1
L38_1 = "其实，我已经和店长约好……如果到下周前，新品甜点的销售业绩还不好的话，就要下架。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Ehrlich gesagt habe ich der Geschäftsführerin versprochen, dass ich wir das Menü streichen, wenn es sich bis nächste Woche nicht gut verkauft."
L37_1.m_Talk_DEU = L38_1
L38_1 = "En fait, j'ai promis à ma patronne que j'allais enlever mon dessert de la carte s'il ne rencontrait pas le succès escompté."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "COUNTERCASE_YUNA_NORMAL_4@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 30914
L38_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_StartFXSoundName = "FX_CUTSCEN_BEEP"
L38_1.m_CharStrID = "MINT♥WITCH_COUNTERCASE_NULL"
L39_1 = "그래서… 혹시 괜찮다면 민초 협회 분들이 제 신메뉴를 드셔보셨으면 해요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "それで……もしよかったら、みなさんに私の新メニューを召し上がっていただきたいんです。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "So... I was wondering if the MC Society members would like to come and try my new dessert."
L38_1.m_Talk_ENG = L39_1
L39_1 = "所以…我想拜託超薄協會的各位，可以來嚐嚐我做的新甜點嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เลย...ฉันสงสัยว่าสมาชิกสมาคม MC  จะมาลองชิมขนมใหม่ของผมหรือเปล่า"
L38_1.m_Talk_THA = L39_1
L39_1 = "Vì vậy... tôi đang tự hỏi liệu các thành viên Hội có muốn đến và thử món tráng miệng mới của tôi không."
L38_1.m_Talk_VTN = L39_1
L39_1 = "所以……如果可以，我希望薄荷巧克力协会的人能尝尝我的新品甜点。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Deshalb ... wünsche ich mir, dass die Mitglieder des Minzschoko-Vereins mein neues Menü probieren."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Alors... Est-ce que les membres de votre association accepteraient de venir le goûter, pendant qu'il est encore temps ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
