L39_1.m_CharStrID = "MINCHO_BOSS_COUNTERCASE_NULL"
L40_1 = "아하! 마침 잘 됐군요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "なるほど！　それならお力添えできそうです。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Aha! That would be nice."
L39_1.m_Talk_ENG = L40_1
L40_1 = "喔喔～！這麼巧！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "อ๋อ! นั่นคงจะดี"
L39_1.m_Talk_THA = L40_1
L40_1 = "Aha! Thật là tốt."
L39_1.m_Talk_VTN = L40_1
L40_1 = "啊哈！那正好。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Aha! Das trifft sich gut."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Oh ! Quelle heureuse coïncidence !"
