L40_1.m_EndFXSoundName = "TYPING_LOOP"
L40_1.m_CharStrID = "MINCHO_BOSS_COUNTERCASE_NULL"
L41_1 = "마침 저희 협회에서도 첫 정모를 준비하고 있던 참이었습니다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "ちょうど我々の協会で初となるオフ会を設けようとしていまして。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Because we were actually planning our first offline meeting, you see."
L40_1.m_Talk_ENG = L41_1
L41_1 = "剛好我們協會準備要辦第一場聚會。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เนื่องจากเรากำลังวางแผนการประชุมออฟไลน์ครั้งแรกจริงๆ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Bởi vì thực ra chúng tôi đã lên kế hoạch cho cuộc họp online đầu tiên, cô thấy đấy."
L40_1.m_Talk_VTN = L41_1
L41_1 = "正好我们协会也在筹备第一次成员定期聚会。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Wir im Verein wollten sowieso bald unseren ersten Stammtisch veranstalten."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Nous avions justement prévu d'organiser une première rencontre avec les membres de l'association."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "COUNTERCASE_YUNA_NORMAL_4@41#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 41
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 30914
L41_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_StartFXSoundControl = "NCSC_LOOP_PLAY"
L41_1.m_StartFXSoundName = "TYPING_LOOP"
L41_1.m_EndFXSoundControl = "NCSC_STOP"
L41_1.m_EndFXSoundName = "TYPING_LOOP"
L41_1.m_CharStrID = "MINCHO_BOSS_COUNTERCASE_NULL"
L42_1 = "인터넷으로만 만나는 사이라서 저희도 협회원들끼리 얼굴을 잘 모르거든요."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ネット上での繋がりなので、まだ協会員同士も顔がわからないのです。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "We’ve only been talking to each other online, so we barely know each other’s faces."
L41_1.m_Talk_ENG = L42_1
L42_1 = "因為大家都只在線上聊過天，所以其實都還不清楚會員們的長相呢。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เราคุยกันแค่ทางออนไลน์ เลยแทบไม่รู้จักหน้ากันเลย"
L41_1.m_Talk_THA = L42_1
L42_1 = "Chúng tôi chỉ nói chuyện với nhau trên mạng nên hầu như không biết mặt nhau."
L41_1.m_Talk_VTN = L42_1
L42_1 = "因为都是网上认识的，所以协会成员们在现实中也不知道对方的相貌。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Denn wir kennen uns untereinander noch nicht vom Sehen, da wir uns nur im Internet unterhalten."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Voyez-vous, nous discutons beaucoup en ligne mais nous n'avons jamais eu l'occasion de nous voir pour de vrai."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "COUNTERCASE_YUNA_NORMAL_4@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 30914
L42_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L42_1.m_bWaitClick = true
