L42_1.m_StartFXSoundName = "FX_CUTSCEN_BEEP"
L42_1.m_CharStrID = "MINT♥WITCH_COUNTERCASE_NULL"
L43_1 = "오! 정말요? 그럼 특별히 민초연합 분들께는 반값에 드릴게요!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "えっ、本当ですか？　それでは特別に、協会の皆さんには半額で提供しますね！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Really? Then I’ll give you a 50% discount!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "哇！真的嗎？那我可以替協會的會員打五折！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "จริงหรือ งั้นฉันจะให้ส่วนลด 50% แก่คุณ!"
L42_1.m_Talk_THA = L43_1
L43_1 = "Thật sự? Vậy thì tôi sẽ giảm giá cho cô 50%!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "哦！真的吗？那我可以给薄荷巧克力协会的人提供半价优惠！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Oh! Wirklich? Dann mache ich extra für die Minzschoko-Vereinigung einen halben Rabatt!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Oh ! Vraiment ? Dans ce cas-là, je peux vous faire une offre de groupe spéciale à moitié-prix !"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
