L43_1.m_CharStrID = "MINT♥WITCH_COUNTERCASE_NULL"
L44_1 = "민트 초코 좋아하는 사람들끼리 이정도는 해줄 수 있죠!"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "チョコミント好きの仲間にこれくらいのサービスは当然です！"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Mint chocolate lovers should help each other, right?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "大家都喜歡薄荷巧克力，就讓我為大家盡一點微薄之力吧！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "คนรักช็อกโกแลตมิ้นต์น่าจะช่วยเหลือกันใช่ไหม?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Những người yêu thích sôcôla bạc hà nên giúp đỡ lẫn nhau phải không?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "大家都是薄荷巧克力的爱好者，优惠完全没问题！"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Unter Minzschoko-Liebhabern tut man sich eben einen Gefallen!"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Entre amateurs de Choco-Menthe, il faut savoir se serrer les coudes !"
L43_1.m_Talk_FRA = L44_1
