L45_1 = "좋군요. 그래서 그 신메뉴 이름이 뭐죠?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ありがとうございます。その新メニューの名前はなんですか？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "That’d be great. So what’s the name of the new menu item?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "好棒，那新甜點的名字是什麼呢？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "นั่นจะดีมาก แล้วเมนูใหม่ชื่ออะไรคะ?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Điều đó thật tuyệt. Vậy tên của mục menu mới là gì?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "太好了。所以新品甜点的名称是什么？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Schön. Und wie heißt dieses neue Menü?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Très bien. Et comment s'appelle ce nouveau dessert ?"
L44_1.m_Talk_FRA = L45_1
