L45_1.m_CharStrID = "MINT♥WITCH_COUNTERCASE_NULL"
L46_1 = "<color=#ffd34c>민트 초코 오믈렛</color>! 제 자신작이니까 기대하셔도 좋아요!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "<color=#ffd34c>チョコミントオムレツ</color>！　私の自信作なのでご期待ください！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "It’s the <color=#ffd34c>Mint Chocolate Omelet</color>! It’s my masterpiece!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "<color=#ffd34c>薄荷巧克力歐姆蛋</color>！這可是我的得意之作！敬請期待吧！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "<color=#ffd34c>ไข่เจียวช็อกโกแลตมิ้นต์</color>! มันเป็นผลงานชิ้นเอกของฉัน!"
L45_1.m_Talk_THA = L46_1
L46_1 = "Đó là <color=#ffd34c>Trứng tráng sôcôla bạc hà</color>! Đó là kiệt tác của tôi!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "<color=#ffd34c>薄荷巧克力煎蛋卷</color>！是我的新品，敬请期待吧！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "<color=#ffd34c>Minzschoko-Omelette</color>! Ich habe mein Herzblut hineingesteckt, also können Sie sich auf etwas freuen!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "L'<color=#ffd34c>omelette choco-menthe</color> ! C'est une création originale, j'ai hâte de vous la proposer !"
L45_1.m_Talk_FRA = L46_1
