L47_1.m_CharStrID = "MINCHO_BOSS_COUNTERCASE_NULL"
L48_1 = "그런 메뉴라면 아무도 시킬 것 같지 않아서 적절할 것 같네요."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "そんなメニューなら誰も頼まないだろうし、大丈夫でしょうね。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "I suppose it will be perfect since no one else would order such a thing."
L47_1.m_Talk_ENG = L48_1
L48_1 = "應該不太會有人點這道甜點吧？很適合拿來當作通關密碼呢。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฉันคิดว่ามันคงจะสมบูรณ์แบบเพราะไม่มีใครสั่งอะไรแบบนี้อีกแล้ว"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi cho rằng nó sẽ hoàn hảo vì không ai khác lại đặt mua một thứ như vậy."
L47_1.m_Talk_VTN = L48_1
L48_1 = "如果是这个的话……应该没人会点吧。作为接头暗号很适合呢。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Das klingt angemessen, da es so klingt, als ob es niemand bestellen würde."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Avec un menu pareil, nous n'aurons aucun mal à nous identifier. Après tout, qui irait commander ça ?"
L47_1.m_Talk_FRA = L48_1
