L49_1 = "좋습니다. 그럼 정모 날짜가 정해지면 따로 연락 드리겠습니다."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "承知しました。それではオフ会の日時が決まり次第、改めてご連絡申し上げます。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Good. Then I’ll let you know when the date is set."
L48_1.m_Talk_ENG = L49_1
L49_1 = "好，那聚會的時間確定後我再跟你聯絡。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ดี. แล้วจะแจ้งให้ทราบเมื่อกำหนดวันครับ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Tốt. Thế tôi sẽ cho cô biết thời gian sau nhé"
L48_1.m_Talk_VTN = L49_1
L49_1 = "那好，定好聚会的日子，我会另行通知你。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Einverstanden. Dann melden wir uns, sobald das Datum für den Stammtisch feststeht."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Très bien. Je vous contacterai lorsque nous aurons fixé la date de notre première réunion officielle."
L48_1.m_Talk_FRA = L49_1
