L11_1.m_CharStrID = L12_1
L12_1 = "R_M_I"
L11_1.m_Pos = L12_1
L12_1 = "뭐야, 오늘따라 묘하게 기분 좋아보이는 표정인데?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "なんだ、今日はやけにご機嫌だな。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "You seem very happy today, Yuna."
L11_1.m_Talk_ENG = L12_1
L12_1 = "你幹嘛？今天好像心情特別好？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "วันนี้คุณดูมีความสุขมากนะยูนา"
L11_1.m_Talk_THA = L12_1
L12_1 = "Hôm nay nhóc có vẻ rất vui, Yuna."
L11_1.m_Talk_VTN = L12_1
L12_1 = "呦，看你的表情，今天的心情很好呢？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Hey, warum siehst du heute so komisch gutgelaunt aus?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Qu'est-ce qui t'arrive ? Tu sembles de bonne humeur."
L11_1.m_Talk_FRA = L12_1
