L13_1 = "你沒忘記我們的打賭吧？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "คุณลืมเหรอ?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Nhóc đã quên à?"
