L13_1 = "不会是忘记了吧？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Hast du es etwa vergessen?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Tu n'as pas oublié, j'espère ?"
