L14_1 = "R"
L13_1.m_Pos = L14_1
L14_1 = "오늘까지 그 저주받은 녹색 계란 부침이 판매량을 못 채울 경우…."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "今日までにあの呪われた薄緑の卵焼きの販売実績が芳しくなかったら……"
L13_1.m_Talk_JPN = L14_1
L14_1 = "If your accursed green egg fries don’t sell well today..."
L13_1.m_Talk_ENG = L14_1
L14_1 = "要是今天那個受到詛咒的綠色雞蛋煎餅還是賣不好的話…"
L13_1.m_Talk_TWN = L14_1
L14_1 = "หากวันนี้เฟรนช์ฟรายส์ไข่เขียวที่ถูกสาปของคุณขายไม่ดี..."
L13_1.m_Talk_THA = L14_1
L14_1 = "Nếu món khoai tây chiên trứng xanh đáng nguyền rủa của nhóc hôm nay không bán chạy..."
L13_1.m_Talk_VTN = L14_1
L14_1 = "如果到今天为止，那个该死的绿色蛋卷销量还是不行的话……"
L13_1.m_Talk_SCN = L14_1
