L29_1 = "여기 민트 초코 오믈렛이란 메뉴 있지? 그것 좀 주쇼."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "チョコミントオムレツってあるよな？　それをくれ。"
