L44_1.m_Pos = L45_1
L45_1 = "봤지? 봤지, 봤지~? 이제 민초의 위대함을 알겠어, 라우라?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ねえねえ見た？ 見た～？　これでもうチョコミントの偉大さがわかったよね？　ラウラ。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "You see? You see? Do you see the greatness of mint chocolate now, Laura?"
L44_1.m_Talk_ENG = L45_1
L45_1 = "看到沒有！！知道薄荷巧克力的厲害了吧，蘿拉？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "คุณเห็นไหม? คุณเห็นไหม? ตอนนี้คุณเห็นความยิ่งใหญ่ของช็อกโกแลตมิ้นต์แล้วหรือยังลอร่า?"
L44_1.m_Talk_THA = L45_1
L45_1 = "Cô thấy không? Cô thấy không? Bây giờ cô đã thấy sự tuyệt vời của sô cô la bạc hà chưa, Laura?"
L44_1.m_Talk_VTN = L45_1
L45_1 = "看到了吧？看到没~？现在该知道薄荷巧克力的伟大之处了吧，劳拉？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Siehst du? Siehst du, siehst du? Verstehst du jetzt, wie erhaben Minzschoko ist, Laura?"
L44_1.m_Talk_DEU = L45_1
L45_1 = "T'as vu ? T'as vu ? J'espère que tu réalises un peu mieux la grandeur du chocolat à la menthe, maintenant !"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "COUNTERCASE_YUNA_NORMAL_4@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 30914
L45_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L45_1.m_bWaitClick = true
