L46_1 = "LAURA_STREGA_EVENT_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "R"
L45_1.m_Pos = L46_1
L45_1.m_Crash = 30
L46_1 = "마, 말도 안돼. 진짜로 이딴 걸 돈 주고 사 먹는 녀석들이 있단 말이야?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "あ、ありえない。こんなものを金を払ってまで食べたがるやつらが存在するだと？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "N-no way. There are actually people who are willing to pay for this?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "怎，怎麼可能？真的有人會花錢買這種東西嗎？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "มะ-ไม่มีทาง มีคนยินดีจ่ายจริงเหรอ?"
L45_1.m_Talk_THA = L46_1
L46_1 = "K-không thể nào. Thực sự có những người sẵn sàng trả tiền cho việc này?"
L45_1.m_Talk_VTN = L46_1
L46_1 = "怎、怎么可能。真的有人会花钱吃这种东西吗？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "D-das macht null Sinn. Wer in aller Welt bezahlt Geld dafür, um so einen Mist zu essen?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "I-Impossible. Il y a des gens qui paient pour manger cette... chose ?"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
