L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "……流行というのはまったく理解に苦しむものだな。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "It’s really hard to follow trends these days."
L46_1.m_Talk_ENG = L47_1
L47_1 = "…流行還真難懂。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ทุกวันนี้มันยากที่จะติดตามเทรนด์"
L46_1.m_Talk_THA = L47_1
L47_1 = "Thật sự rất khó để theo kịp xu hướng ngày nay."
L46_1.m_Talk_VTN = L47_1
L47_1 = "……现在的时尚潮流果然让人难以理解。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "... Trends sind mir manchmal unbegreiflich."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Ce qui est sûr, c'est que je ne comprendrais jamais rien à la mode..."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "COUNTERCASE_YUNA_NORMAL_4@97#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 97
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 30914
L47_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_SERIOUS"
L47_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L48_1 = "L"
L47_1.m_Pos = L48_1
L47_1.m_Crash = 30
L48_1 = "흥, 이런 거라니! 원래 유행은 따라가는 게 아니라 앞서 나가는 거라고."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "こんなものってひどい！　流行っていうのは追いかけるんじゃなく、先取りするものだよ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Hah! A trend is something that you make, not follow."
L47_1.m_Talk_ENG = L48_1
L48_1 = "哼，什麼叫這種東西！所謂的流行不是盲從，流行是要創造的。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฮ่า! เทรนด์คือสิ่งที่คุณสร้างขึ้น ไม่ใช่ทำตาม"
L47_1.m_Talk_THA = L48_1
L48_1 = "Ha! Xu hướng là thứ cô tạo ra chứ không phải theo sau."
L47_1.m_Talk_VTN = L48_1
L48_1 = "哼，别小看我！时尚本身就不是用来追赶的，而是用来超越的才对。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Hmpf, von wegen Mist! Trends folgen nicht, sondern sie führen an."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Cette « chose », tu dis ? Et puis il ne faut pas se contenter de suivre la mode, il faut savoir la devancer."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
