L49_1.m_Face = L50_1
L49_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L49_1.m_Pos = "C"
L50_1 = "좋았어. 이 메뉴를 발판으로 좀 더 대중적인 민트 초코 디저트를……"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "よし。このメニューをきっかけに、みんなに愛されるチョコミントのスイーツを……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Alright. Now I’m going to make another mint chocolate dessert that’s more approachable..."
L49_1.m_Talk_ENG = L50_1
L50_1 = "很好，那我要繼續創作更大眾化的薄荷巧克力甜點……"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ใช้ได้. ตอนนี้ฉันกำลังจะทำของหวานช็อกโกแลตมิ้นต์ที่เข้าถึงได้ง่ายขึ้นอีกชิ้นหนึ่ง..."
L49_1.m_Talk_THA = L50_1
L50_1 = "Được rồi. Bây giờ tôi sẽ làm một món tráng miệng sô cô la bạc hà khác dễ tiếp cận hơn..."
L49_1.m_Talk_VTN = L50_1
L50_1 = "很好。将这次的新品作为起点，再研发出更加大众化的薄荷巧克力甜点……"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Es läuft super. Auf Basis dieses Menüs werde ich ein noch massentauglicheres Minzschoko-Menü ..."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Parfait. J'espère que ce plat sera celui qui permettra de populariser le chocolat à la menthe..."
L49_1.m_Talk_FRA = L50_1
