L4_1.m_CharStrID = L5_1
L5_1 = "지금 이걸 먹으라고 내놓은 거야!? 오믈렛에서 치약 맛이 나잖아!!"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "こんなのを食えってのか！？　オムレツから歯磨き粉みたいな味がするぞ！！"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Yeah, what is this? It tastes like toothpaste!"
L4_1.m_Talk_ENG = L5_1
L5_1 = "這東西是給人吃的嗎？！歐姆蛋怎麼會有牙膏的味道！！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ใช่นี่คืออะไร? รสชาติเหมือนยาสีฟัน!"
L4_1.m_Talk_THA = L5_1
L5_1 = "Vâng, đây là gì? Nó có vị như kem đánh răng!"
L4_1.m_Talk_VTN = L5_1
L5_1 = "现在是让我吃这种东西吗！？煎蛋卷上有一种牙膏的味道！！"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Soll ich diesen Fraß hier essen, oder wie?! Das Omelette schmeckt nach Zahnpasta!!!"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Vous vous moquez de moi ? Vous osez mettre ce genre de plat sur votre carte ? Cette omelette a un goût de dentifrice !"
