L8_1 = "MINCHO_MOB1_COUNTERCASE_NULL"
L7_1.m_CharStrID = L8_1
L8_1 = "아무리 같은 협회원이 일하는 카페라고 해도…… 이건 음식이 너무 심한데요?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "いくら同じ協会員が働くカフェとはいえ……これは食べ物としてひどすぎませんか？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I know you’re one of us... but this food is just horrible!"
L7_1.m_Talk_ENG = L8_1
L8_1 = "就算要我們來捧會員的場……也不該端出這種東西吧？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ฉันรู้ว่าคุณเป็นหนึ่งในพวกเรา... แต่อาหารนี่แย่มาก!"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tôi biết cô là một trong số chúng tôi... nhưng món ăn này thật kinh khủng!"
L7_1.m_Talk_VTN = L8_1
L8_1 = "就算是同一个协会成员工作的咖啡店……但让我吃这种东西也太过分了吧？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Selbst wenn einer unseres Vereins hier im Café arbeitet ... dieses Gericht ist unzumutbar."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Vous faites peut-être partie de l'association mais... ce plat est infect."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "COUNTERCASE_YUNA_NORMAL_4@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 30914
L8_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
