L8_1.m_fWaitTime = 0
L9_1 = "MINCHO_MBOSS_COUNTERCASE_NULL"
L8_1.m_CharStrID = L9_1
L9_1 = "민트에…… 초코에…… 오믈렛. 끔찍한 혼종."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "ミントに……チョコに……オムレツ。もはやカオス。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Mint... chocolate... in an omelet... It’s just disastrous."
L8_1.m_Talk_ENG = L9_1
L9_1 = "薄荷……巧克力……歐姆蛋。驚人的組合。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "มิ้นต์... ช็อกโกแลต... ในไข่เจียว... หายนะจริงๆ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Bạc hà... sô cô la... trong món trứng tráng... Thật là thảm họa."
L8_1.m_Talk_VTN = L9_1
L9_1 = "薄荷……巧克力……煎蛋卷。真是恐怖的组合。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Minze ... Schokolade ... und Omelette. Diese Kombination gehört verboten."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Une omelette... avec du chocolat... et de la menthe. Quel mélange immonde !"
L8_1.m_Talk_FRA = L9_1
