L9_1.m_fBGCrashTime = 0.5
L10_1 = "MINCHO_MOB2_COUNTERCASE_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "이거 어쩔 거야? 난 이런 음식 같지도 않은 음식에 나는 한 푼도 못내."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "どうしてくれるんだ。俺はこんなものには一銭たりとも払いたくないね。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "What are you going to do? I ain’t gonna pay for this terrible thing."
L9_1.m_Talk_ENG = L10_1
L10_1 = "你說該怎麼辦？這種東西我一口也吃不下！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "คุณกำลังจะทำอะไร? ฉันจะไม่จ่ายเงินสำหรับสิ่งที่เลวร้ายนี้"
L9_1.m_Talk_THA = L10_1
L10_1 = "Cô định làm gì? Tôi sẽ không trả tiền cho món khủng khiếp này."
L9_1.m_Talk_VTN = L10_1
L10_1 = "现在要怎么办？我可不会为这种完全不像食物的东西付钱。"
L9_1.m_Talk_SCN = L10_1
