L10_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L10_1.m_Pos = "C"
L10_1.m_Crash = 20
L11_1 = "그, 그렇지만 다들 민초 협회잖아요?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "で、でもみなさんチョコミント協会の方々ですよね？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "But you’re all from MC Society, right?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "可，可是你們不是薄巧協會的嗎？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "แต่พวกคุณทุกคนมาจากสมาคม MC ใช่ไหม?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Nhưng tất cả các cô đều đến từ Hội Sô Cô La Bạc Hà phải không?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "但、但是大家不都是薄荷巧克力协会成员吗？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "A-aber Sie sind doch alle vom Minzschoko-Verein?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Mais... Vous faites partie de l'association CM, non ?"
L10_1.m_Talk_FRA = L11_1
