L11_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L11_1.m_Pos = "C"
L12_1 = "다들 민트 초코를 좋아하시는게……."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "みんなチョコミントが好きなんじゃ……"
L11_1.m_Talk_JPN = L12_1
L12_1 = "You all love mint chocolate..."
L11_1.m_Talk_ENG = L12_1
L12_1 = "你們不是也喜歡薄荷巧克力嗎……"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ใครๆ ก็ชอบช็อกโกแลตมิ้นต์..."
L11_1.m_Talk_THA = L12_1
L12_1 = "Tất cả đều yêu thích sô cô la bạc hà..."
L11_1.m_Talk_VTN = L12_1
L12_1 = "应该喜欢薄荷巧克力才对吧……"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Deshalb lieben Sie doch alle Minzschoko, oder ...?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je pensais que tout le monde aimerait le chocolat à la menthe..."
L11_1.m_Talk_FRA = L12_1
