L14_1 = "MINCHO_MOB2_COUNTERCASE_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "민트 초코? 그딴 게 협회랑 무슨 상관이야?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "チョコミント？　そんなものが協会となんの関係があるんだ？"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Mint chocolate? What’s it got to do with our Society?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "薄荷巧克力？薄荷巧克力和協會有什麼關係？"
L13_1.m_Talk_TWN = L14_1
L14_1 = " ช็อคโกแลตมิ้นท์? เกี่ยวอะไรกับสมาคมเรา?"
L13_1.m_Talk_THA = L14_1
L14_1 = "Sôcôla bạc hà? Nó có liên quan gì tới Hội chúng ta?"
L13_1.m_Talk_VTN = L14_1
L14_1 = "薄荷巧克力？这跟协会有什么关系？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Minzschoko? Was hat so ein Zeug mit dem Verein zu tun?"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Du chocolat à la menthe ? Mais quel rapport avec notre association ?"
L13_1.m_Talk_FRA = L14_1
