L15_1 = "COUNTERCASE_YUNA_NORMAL_4@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 30914
L14_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "MINCHO_MOB2_COUNTERCASE_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "나는 그냥 대표가 시킨대로 여기서 특정 메뉴를 시켜, 서로의 얼굴을……"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "俺は代表の指示どおり、ここで特定のメニューを頼んで、お互いの顔を……"
L14_1.m_Talk_JPN = L15_1
L15_1 = "All I heard from the leader was to order a specific dish in this cafe, and check each other’s faces..."
L14_1.m_Talk_ENG = L15_1
L15_1 = "是會長叫我來我才來的，我們根本連臉都……"
L14_1.m_Talk_TWN = L15_1
L15_1 = "สิ่งเดียวที่ฉันได้ยินจากผู้นำคือการสั่งอาหารจานพิเศษในร้านกาแฟแห่งนี้ และตรวจหน้ากัน..."
L14_1.m_Talk_THA = L15_1
L15_1 = "Tất cả những gì tôi nghe được từ hội trưởng là gọi một món ăn cụ thể trong quán cà phê này và kiểm tra khuôn mặt của nhau..."
L14_1.m_Talk_VTN = L15_1
L15_1 = "我只是按照会长的要求，在这里点特定甜点作为暗号，与协会成员们混个脸熟而已……"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Mir wurde lediglich vom Vorsitzenden aufgetragen, hier ein bestimmtes Menü zu bestellen, damit wir uns gegenseitig erkennen ..."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Moi, j'ai simplement suivi les ordres du directeur qui m'a dit de commander un plat préalablement fixé pour vérifier l'identité de chacun..."
L14_1.m_Talk_FRA = L15_1
