L29_1 = "COUNTERCASE_YUNA_NORMAL_4@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 30914
L28_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
