L29_1 = "SOYEONG_POLICE_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "자, 손님 분들 주목!!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "はい、みなさんご注目ください！！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Everyone, attention!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "請各位注意！！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ทุกคนฟังนะ!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Mọi người chú ý nhé!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "各位顾客请注意！！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "So, werte Gäste, alle mal herschauen!!!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "À tous les clients ! Je demande votre attention !"
L28_1.m_Talk_FRA = L29_1
