L30_1 = "COUNTERCASE_YUNA_NORMAL_4@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 30914
L29_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "SOYEONG_POLICE_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "이 중, 민트 초코 오믈렛이라는 메뉴를 시킨 분들은 얌전히 손을 머리 위로 올리고 바닥에 엎드려 주세요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "この中でチョコミントオムレツというメニューを頼んだ方は、\n大人しくうつ伏せになって手を頭の上に乗せてください。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Everyone who ordered a Mint Chocolate Omelet; put your hands on your heads, and lie down on the ground."
L29_1.m_Talk_ENG = L30_1
L30_1 = "請有點這道薄荷巧克力歐姆蛋的人趴在地上。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ทุกคนที่สั่ง  ไข่เจียวช็อคโกแลตมิ้นท์; วางมือบนศีรษะและนอนราบกับพื้น"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tất cả những người đã đặt món Trứng tráng sô cô la bạc hà; đặt tay lên đầu và nằm xuống đất."
L29_1.m_Talk_VTN = L30_1
L30_1 = "在这里，点了薄荷巧克力煎蛋卷的人，乖乖把手举到头顶，然后趴在地下。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Diejenigen hier, die das Minzschoko-Omelette bestellt haben, heben bitte ihre Hände an den Kopf und legen sich bäuchlings auf den Boden."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Que tous ceux qui ont commandé une omelette choco-menthe posent leurs mains sur la tête et se mettent à plat ventre."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "COUNTERCASE_YUNA_NORMAL_4@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 30914
L30_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "UNIT_LAUGH"
L30_1.m_Face = L31_1
L31_1 = "SOYEONG_POLICE_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "이유는 본인들이 더 잘 알고 있겠죠? 암전히 협조해주세요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "理由はご自身がおわかりですよね？　大人しく協力してくださいね。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "You know why we’re here. Do not resist, and cooperate."
L30_1.m_Talk_ENG = L31_1
L31_1 = "理由應該不用我說吧？麻煩乖乖配合。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "คุณรู้ไหมว่าทำไมเราถึงมาที่นี่ อย่าต่อต้านและให้ความร่วมมือ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Các người biết tại sao chúng tôi ở đây. Đừng chống cự mà hãy hợp tác."
L30_1.m_Talk_VTN = L31_1
L31_1 = "理由不需要我说明，自己也都清楚吧？请乖乖合作。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Den Grund kennen Sie wohl selbst. Ich würde an Ihrer Stelle kooperieren."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je n'ai pas besoin d'expliquer pourquoi, n'est-ce pas ? Et n'essayez pas de résister."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
