L33_1 = "COUNTERCASE_YUNA_NORMAL_4@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 30914
L32_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_BGCrash = 30
L32_1.m_fBGCrashTime = 0.5
L33_1 = "MINCHO_MOB1_COUNTERCASE_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "아! 아야! 자, 잠깐만요! 누님, 팔 꺾지 마요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "いっ、いたたた！　ちょ、ちょっとお姉さん、腕が痛いです。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Ouch! Ouch! Ma’am, you’re hurting my arms!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "唉唷唷！小力一點！我的手臂要被凹斷啦！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "อุ๊ย! อุ๊ย! คุณผู้หญิง คุณกำลังทำแขนของฉันเจ็บ!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Ôi! Ôi! Thưa cô, cô đang làm đau tay tôi đấy!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "啊，好疼！等、等下！大姐，别扭我的胳膊。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Au! Auaa! M-Moment! Hey, bitte nicht meinen Arm verrenken."
L32_1.m_Talk_DEU = L33_1
L33_1 = "A-ïe ! Attendez ! Madame, vous me faites mal au bras !"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "COUNTERCASE_YUNA_NORMAL_4@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 30914
L33_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "MINCHO_MOB2_COUNTERCASE_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "젠장, 역시 함정이었나. 어쩐지 이상하다 했어."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "くそ！　やっぱり罠だったか。おかしいと思ったんだ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "So it was a trap. I thought it was fishy."
L33_1.m_Talk_ENG = L34_1
L34_1 = "該死，果然是陷阱，難怪這麼詭異。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ดังนั้นมันจึงเป็นกับดัก ฉันคิดว่ามันผิด"
L33_1.m_Talk_THA = L34_1
L34_1 = "Vậy đó là một cái bẫy. Tôi đã nghĩ nó có mùi sai sai."
L33_1.m_Talk_VTN = L34_1
L34_1 = "该死，果然是陷阱。早就觉得不对劲。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Verdammt, das war also doch eine Falle. Ich dachte mir schon, dass etwas nicht stimmt."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Mince ! C'était un piège ? Je me disais bien que c'était étrange."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "COUNTERCASE_YUNA_NORMAL_4@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 30914
L34_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "MINCHO_MBOSS_COUNTERCASE_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "……대표, 대표는 어디있지?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "……代表、代表はどこだ？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Where is our leader?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "……會長呢？會長在哪裡？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ผู้นำของเราอยู่ที่ไหน?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Thủ lĩnh của chúng ta đâu?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "……会长，会长在哪？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "... Der Vorsitzende, wo ist der Vorsitzende?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Le directeur ! Où est le directeur ?"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "COUNTERCASE_YUNA_NORMAL_4@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 30914
L35_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_IDLE"
L36_1 = "SOYEONG_POLICE_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "아아, 정모 장소가 바뀐 것 같더라고. 구치소에서 먼저 기다리고 있겠다는데?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "ああ、オフ会の場所が変わったみたいです。先に拘置所で待ってるらしいですよ。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Oh, your offline meeting location has changed. He’s waiting for you in prison."
L35_1.m_Talk_ENG = L36_1
L36_1 = "喔喔～你們的聚會地點好像換咧，會長在拘留所等你們。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "โอ้ สถานที่ประชุมออฟไลน์ของคุณมีการเปลี่ยนแปลง เขารอคุณอยู่ในคุก"
L35_1.m_Talk_THA = L36_1
L36_1 = "Ồ, địa điểm họp offline của các người đã thay đổi. Hắn đang đợi trong tù."
L35_1.m_Talk_VTN = L36_1
L36_1 = "啊啊，你们定期聚会的场所临时有变更哦。他说先去拘留所等你们？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ach, der Treffpunkt soll sich geändert haben. Er soll in Untersuchungshaft auf Sie alle warten."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Oh, le lieu de la réunion a été modifié, il ne vous a pas prévenu ? Celle-ci aura lieu directement... en prison !"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "COUNTERCASE_YUNA_NORMAL_4@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 30914
L36_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "SOYEONG_POLICE_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "디저트는 콩밥으로도 괜찮죠?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "デザートは臭い飯で構いませんよね？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "You can enjoy your dessert in the slammer."
L36_1.m_Talk_ENG = L37_1
L37_1 = "到牢裡吃牢飯吧！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "คุณสามารถเพลิดเพลินกับของหวานของคุณได้ในกรงขัง"
L36_1.m_Talk_THA = L37_1
L37_1 = "Các người có thể thưởng thức món tráng miệng của mình sau nhé."
L36_1.m_Talk_VTN = L37_1
L37_1 = "甜点的话，牢饭应该比较适合？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Als Nachtisch gibt es Wasser und Brot, okay?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Vous profiterez du dessert dans votre cellule."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
