L39_1 = "COUNTERCASE_YUNA_NORMAL_4@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 30914
L38_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "MINCHO_MBOSS_COUNTERCASE_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "그렇군. 벌써 잡힌 건가."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "そうか、もう捕まったのか。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "So he’s already caught?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "原來如此，已經被抓到了嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แล้วเขาถูกจับแล้วเหรอ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Vậy là anh ta đã bị bắt rồi à?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "原来如此。是已经被抓了吗。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "So sieht‘s aus. Wir wurden bereits erwischt."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Vous l'avez déjà attrapé, c'est ça... ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "COUNTERCASE_YUNA_NORMAL_4@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 30914
L39_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "MINCHO_MBOSS_COUNTERCASE_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "협회원끼리도 서로 얼굴을 모른다는 걸 역이용하디니……"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "協会員同士でも顔を知らないことが裏目に出たな……"
L39_1.m_Talk_JPN = L40_1
L40_1 = "You used the fact that we didn’t know each other’s faces..."
L39_1.m_Talk_ENG = L40_1
L40_1 = "竟然利用會員們都沒見過彼此這一點反將一軍……"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เธอใช้ความจริงที่ว่าเราไม่รู้จักกัน..."
L39_1.m_Talk_THA = L40_1
L40_1 = "Mày lợi dụng việc chúng ta không biết mặt nhau..."
L39_1.m_Talk_VTN = L40_1
L40_1 = "竟然反过来利用协会成员们互相不认识的漏洞……"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Sie haben die Tatsache ausgenutzt, dass selbst die Vereinsmitglieder gegenseitig nicht wissen, wie wir aussehen ..."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Je vois, vous avez tiré avantage du fait que les membres ne connaissent pas le visage des uns et des autres..."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "COUNTERCASE_YUNA_NORMAL_4@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 30914
L40_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "MINCHO_MBOSS_COUNTERCASE_NULL"
L40_1.m_CharStrID = L41_1
L41_1 = "경찰 쪽도 꽤 하는군."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "警察もなかなかやるな。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "You’re pretty good for a cop."
L40_1.m_Talk_ENG = L41_1
L41_1 = "警察也蠻有兩下子的嘛。"
