L46_1 = "SOYEONG_POLICE_NULL_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "협조 감사합니다. 카페 스트레가의 점장님. ……그리고 유나 씨."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "ご協力ありがとうございました、カフェストレガの店長。……そしてユナさん。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Thank you for your cooperation, Cafe Strega management... and Yuna."
L45_1.m_Talk_ENG = L46_1
L46_1 = "謝謝你們的配合，史特雷加咖啡廳的店長……還有尤娜也是。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ขอขอบคุณสำหรับความร่วมมือ ผู้บริหารสเตรก้าคาเฟ่... และ ยูนา"
L45_1.m_Talk_THA = L46_1
L46_1 = "Cảm ơn sự hợp tác của cô, ban quản lý Cafe Strega... và Yuna."
L45_1.m_Talk_VTN = L46_1
L46_1 = "感谢配合。史特雷加咖啡店的店长……还有尤娜小姐。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Vielen Dank für die Kooperation an die Geschäftsführerin von Café Strega ... und an Yuna."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Merci pour votre coopération, madame la gérante. Et vous aussi, miss Yuna."
L45_1.m_Talk_FRA = L46_1
