L48_1 = "두 분 덕분에 범죄 조직을 일망타진할 수 있었습니다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "お二人のおかげで犯罪組織を一網打尽にすることができました。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "We caught a gang of criminals thanks to you."
L47_1.m_Talk_ENG = L48_1
L48_1 = "多虧有你們的幫忙，我們才能將犯罪組織一網打盡。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เราจับแก๊งอาชญากรได้ต้องขอบคุณคุณ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Chúng tôi đã bắt được một nhóm tội phạm nhờ có cô."
L47_1.m_Talk_VTN = L48_1
L48_1 = "多亏了两位，我们才能将犯罪组织一网打尽。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Dank euch beiden konnten wir eine Kriminalbande dingfest machen."
L47_1.m_Talk_DEU = L48_1
L48_1 = "C'est grâce à vous que nous avons pu arrêter cette organisation criminelle."
L47_1.m_Talk_FRA = L48_1
