L4_1 = "COUNTERCASE_YUNA_NORMAL_4@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 30914
L3_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_IDLE"
L4_1 = "SOYEONG_POLICE_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "R"
L3_1.m_Pos = L4_1
L4_1 = "하긴, 아직 세간에 널리 알려진 조직은 아니죠."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "確かに、世間に知れ渡っている組織ではありませんね。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Well, they aren’t very popular among the public."
L3_1.m_Talk_ENG = L4_1
L4_1 = "也是啦，畢竟這個組織也還沒出名到人盡皆知。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "พวกมันไม่ได้รับความนิยมในหมู่ประชาชนมากนัก"
L3_1.m_Talk_THA = L4_1
L4_1 = "Chà, chúng không được công chúng ưa chuộng lắm."
L3_1.m_Talk_VTN = L4_1
L4_1 = "也是呢，毕竟不是什么广为人知的组织。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Das macht Sinn, denn diese Bande ist noch nicht sehr bekannt."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Après tout, c'est vrai qu'elle n'est pas si connue."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "COUNTERCASE_YUNA_NORMAL_4@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 30914
