L5_1 = "SOYEONG_POLICE_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "R"
L4_1.m_Pos = L5_1
L5_1 = "이 녀석들은 민간 초능력자 협력회. 속칭 민초 협회라고 불려요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "こいつらは「超能力者民間協会」。通称、チョウミン協会と呼ばれています。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "They are called the Mad for Counters Society, a.k.a. MC Society."
L4_1.m_Talk_ENG = L5_1
L5_1 = "這個組織叫作超能力者博愛協會，簡稱超博協會。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "พวกเขาถูกเรียกว่า พวกบ้าสมาคมเคาน์เตอร์ หรือที่รู้จักกันในชื่อสมาคม MC  "
L4_1.m_Talk_THA = L5_1
L5_1 = "Họ được gọi là Hiệp hội Mad for Counters, (Hiệp hội MC)."
L4_1.m_Talk_VTN = L5_1
L5_1 = "这些家伙们原本是民间超能力者的协会，伪装成了薄荷巧克力协会而已。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Sie nennen sich die Minimal Zuständige Schlawiner-Okkultisten-Obervereinigung – kurzgesagt, Minzschoko-Verein."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Il s'agissait de l'association des Counters Malicieux, plus communément désignée l'association CM."
L4_1.m_Talk_FRA = L5_1
