L10_1 = "R"
L9_1.m_Pos = L10_1
L10_1 = "네, 맹목적으로 카운터의 힘을 숭배하는 탓에 카운터 범죄자의 신분 세탁을 돕거나,"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "はい。カウンターの力を崇拝するあまり、カウンター犯罪者の身分の偽装に手を貸したり、"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Yes. They worship Counters blindly, and they’ve been helping criminal Counters in every way possible."
L9_1.m_Talk_ENG = L10_1
L10_1 = "是的，他們是一盲目崇拜制裁者能力的人，因此還替制裁者罪犯辦假身分，"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ใช่. พวกเขาบูชาเคาน์เตอร์อย่างสุ่มสี่สุ่มห้า และช่วยเหลือเคาน์เตอร์อาชญากรในทุกวิถีทางที่ทำได้"
L9_1.m_Talk_THA = L10_1
L10_1 = "Đúng. Chúng tôn thờ Counters một cách mù quáng và đã giúp đỡ Counters tội phạm bằng mọi cách có thể."
L9_1.m_Talk_VTN = L10_1
L10_1 = "是的，因为他们盲目崇拜制裁者的力量，经常帮制裁者罪犯制作假身份。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Genau. Sie huldigen der Kraft der Counter auf absolute Weise, weshalb sie kriminellen Countern bei der Identitätsfälschung helfen ..."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Oui. Ils vénèrent tellement les Counters qu'ils sont prêts à prêter main-forte à ceux d'entre eux qui exercent des activités criminelles."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "COUNTERCASE_YUNA_NORMAL_4@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 30914
L10_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "SOYEONG_POLICE_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "R"
L10_1.m_Pos = L11_1
L11_1 = "불법적인 루트로 자금줄을 대주는 등…… 관리국 골머리 좀 썩인 녀석들이었죠."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "違法ルートで資金調達をするなど……管理局の頭を悩ませていたやつらでした。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Like helping them change their identities, or funding them through illegal means."
L10_1.m_Talk_ENG = L11_1
L11_1 = "或是當他們背後的金主等等……是管理局的頭痛人物呢。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เช่นการช่วยพวกเขาเปลี่ยนตัวตนหรือให้ทุนสนับสนุนพวกเขาด้วยวิธีที่ผิดกฎหมาย"
L10_1.m_Talk_THA = L11_1
L11_1 = "Giống như giúp thay đổi danh tính hoặc tài trợ bằng các phương tiện bất hợp pháp."
L10_1.m_Talk_VTN = L11_1
L11_1 = "或者用非法手段进行资金援助……算是管理局也很头疼的家伙们。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "oder sie auf illegalem Wege finanziell unterstützen ... solche Sachen. Sie haben der Administration so einige Kopfschmerzen bereitet."
L10_1.m_Talk_DEU = L11_1
L11_1 = "En les aidant par exemple à changer d'identité, ou en les aidant financièrement par des moyens illégaux. L'association a toujours été un problème pour l'Administration."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "COUNTERCASE_YUNA_NORMAL_4@161#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 30914
L11_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "SOYEONG_POLICE_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "R"
L11_1.m_Pos = L12_1
L12_1 = "며칠 전에 녀석들의 대표를 검거했는데."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "数日前に代表は逮捕されましたが……"
L11_1.m_Talk_JPN = L12_1
L12_1 = "We apprehended the Society’s leader a few days ago..."
L11_1.m_Talk_ENG = L12_1
L12_1 = "警方幾天前有抓到他們的會長，"
L11_1.m_Talk_TWN = L12_1
L12_1 = "เราจับกุมผู้นำสมาคมได้เมื่อไม่กี่วันก่อน..."
L11_1.m_Talk_THA = L12_1
L12_1 = "Chúng tôi đã bắt được thủ lĩnh của Hội vài ngày trước..."
L11_1.m_Talk_VTN = L12_1
L12_1 = "在几天前，我们抓住了他们的会长。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Vor einigen Tagen haben wir deren Vorsitzenden verhaftet."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Nous avons appréhendé récemment leur directeur mais..."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "COUNTERCASE_YUNA_NORMAL_4@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 30914
L12_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "SOYEONG_POLICE_NULL_NULL"
L12_1.m_CharStrID = L13_1
L13_1 = "R"
L12_1.m_Pos = L13_1
L13_1 = "민초 협회가 철저하게 점조직으로 운영되고, 구성원 대부분이 방구석 해커들이다보니 다른 협회원의 단서를 잡기가 힘들었어요."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "チョウミン協会は徹底的に隠れて運営されており、構成員のほとんどが\n引きこもりのハッカーで、なかなか尻尾がつかめなかったんですよ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "But the rest of the members were reclusive hackers who didn’t know each other, so it was very difficult to find them."
L12_1.m_Talk_ENG = L13_1
L13_1 = "他們的組織結構嚴密，而且成員大部分是駭客，因此很難找到其他會員的資料。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "แต่สมาชิกที่เหลือเป็นแฮกเกอร์สันโดษที่ไม่รู้จักกันจึงเป็นเรื่องยากมากที่จะตามหาพวกเขา"
L12_1.m_Talk_THA = L13_1
L13_1 = "Nhưng các thành viên còn lại đều là những hacker ẩn dật, không quen biết nhau nên rất khó tìm ra."
L12_1.m_Talk_VTN = L13_1
L13_1 = "因为薄荷巧克力协会的运作方式是彻底的点对点接触，成员们大部分也都是宅在家里的黑客，所以比起其他组织来说，很难进行抓捕。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Doch da der Minzschoko-Verein streng in Knoten organisiert ist und die meisten Mitglieder einsiedlerische Hacker sind, war es schwierig, Anhaltspunkte auf die anderen Vereinsmitglieder zu finden."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Vu que le reste des membres étaient surtout des hackers qui restent enfermés chez eux, nous avions beaucoup de mal à trouver des indices nous permettant de les démasquer."
L12_1.m_Talk_FRA = L13_1
