L15_1 = "UNIT_LAUGH"
L14_1.m_Face = L15_1
L15_1 = "FX_CUTSCEN_TADA"
L14_1.m_StartFXSoundName = L15_1
L15_1 = "SOYEONG_POLICE_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L15_1 = 40
L14_1.m_Crash = L15_1
L15_1 = "……그때, 때마침 운 좋게도!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "……そんな時に、たまたま！"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Then, lucky for us!"
L14_1.m_Talk_ENG = L15_1
L15_1 = "……幸好皇天不負苦心人！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ถ้าอย่างนั้นก็โชคดีสำหรับเรา!"
L14_1.m_Talk_THA = L15_1
L15_1 = "Vậy thì, thật may mắn cho chúng ta!"
L14_1.m_Talk_VTN = L15_1
L15_1 = "……这时候，正好有了绝佳的机会！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "... Aber dann, dann hatten wir Glück!"
L14_1.m_Talk_DEU = L15_1
L15_1 = "... Mais on a eu un coup de chance !"
L14_1.m_Talk_FRA = L15_1
