L16_1 = "COUNTERCASE_YUNA_NORMAL_4@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 30914
L15_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "SOYEONG_POLICE_NULL_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L16_1 = "민초 협회원들이 스트레가라는 카페에서 <color=#ffd34c>이상한 메뉴</color>를 시킬 것이라는 첩보를 얻을 수 있었습니다."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "チョウミン協会員たちがストレガというカフェで<color=#ffd34c>ヘンテコなメニュー</color>を注文するという情報を入手しました。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "We got intel that the members of MC Society were going to order a <color=#ffd34c>particular menu</color> at Cafe Strega."
L15_1.m_Talk_ENG = L16_1
L16_1 = "我們剛好收到情報說超博協會的人會到史特雷加咖啡廳碰頭，暗號就是一道<color=#ffd34c>奇怪的甜點</color>。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "เราได้รับแจ้งว่าสมาชิกของสมาคม MC   กำลังจะสั่ง<color=#ffd34c>เมนูเฉพาะ</color>ที่ สเตรก้าคาเฟ่"
L15_1.m_Talk_THA = L16_1
L16_1 = "Chúng tôi nhận được thông tin rằng các thành viên của MC Society sẽ đặt một <color=#ffd34c>thực đơn đặc biệt</color> tại Cafe Strega."
L15_1.m_Talk_VTN = L16_1
L16_1 = "我们收到了薄荷巧克力协会成员们会在史特雷加咖啡店点<color=#ffd34c>奇怪甜点</color>的情报。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Wir konnten in Erfahrung bringen, dass die Mitglieder des Minzschoko-Vereins in einem Café namens Strega ein <color=#ffd34c>bizarres Menü</color> bestellen werden."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Récemment, on nous a signalé que les membres allaient se réunir au café Strega pour commander un <color=#ffd34c>menu étrange</color>."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "COUNTERCASE_YUNA_NORMAL_4@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 30914
L16_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "SOYEONG_POLICE_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "C"
L17_1 = "이렇게 현장을 잡을 수 있었던 건, 모두 유나 씨의 재치 덕분이에요."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "こうして現場を押さえることができたのは、すべてユナさんの機転のおかげです。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Thank you, Yuna. We arrested them all at once, thanks to your brilliant idea."
L16_1.m_Talk_ENG = L17_1
L17_1 = "我們可以現場逮到犯人都要歸功於尤娜呢。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ขอบคุณยูนา เราจับกุมพวกเขาทั้งหมดได้ในคราวเดียว ต้องขอบคุณความคิดอันยอดเยี่ยมของคุณ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Cảm ơn, Yuna. Chúng tôi đã bắt tất cả bọn chúng cùng một lúc nhờ ý tưởng tuyệt vời của cô."
L16_1.m_Talk_VTN = L17_1
L17_1 = "能在现场抓捕他们，完全多亏了尤娜小姐的聪明才智。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Wir haben es nur deinem Humor zu verdanken, dass wir sie vor Ort festnehmen konnten."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Et c'est grâce à Yuna que vous avons pu les attraper."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "COUNTERCASE_YUNA_NORMAL_4@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 30914
L17_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "UNIT_DESPAIR"
L17_1.m_Face = L18_1
L17_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L17_1.m_Pos = "C"
L17_1.m_Crash = 20
L18_1 = "…세, 세상에 민트 초코를 사랑하는 협회가 아니었다니."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "……そ、そんな、チョコミントを愛する協会じゃなかったなんて。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "S-so they weren’t the Mint Chocolate Club..."
L17_1.m_Talk_ENG = L18_1
L18_1 = "我…我的天啊，原來他們不是喜歡薄荷巧克力的協會。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ก-แปลว่าพวกเขาไม่ใช่ ช็อคโกแลตมิ้นท์ Club..."
L17_1.m_Talk_THA = L18_1
L18_1 = "V-vậy họ không phải là Câu lạc bộ Mint Chocolate (Sôcôla Bạc hà)…"
L17_1.m_Talk_VTN = L18_1
L18_1 = "……天、天啊。竟然不是真心喜欢薄荷巧克力的协会。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "... M-meine Güte, es war also kein Verein der Minzschoko-Fans?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Je n'arrive pas à y croire... Alors ce n'était pas le club Choco-Menthe ?"
L17_1.m_Talk_FRA = L18_1
