L21_1 = "COUNTERCASE_YUNA_NORMAL_4@170#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 30914
L20_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_SURPRISE"
L21_1 = "SOYEONG_POLICE_NULL_NULL"
L20_1.m_CharStrID = L21_1
L21_1 = "R"
L20_1.m_Pos = L21_1
L20_1.m_Crash = 20
L21_1 = "네? 방금 뭐라고 하셨죠?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "はい？　今、なんとおしゃいましたか？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Hmm? What did you say?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "什麼？你剛說什麼？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "อืม? คุณพูดอะไร?"
L20_1.m_Talk_THA = L21_1
L21_1 = "Ừm? cô nói gì?"
L20_1.m_Talk_VTN = L21_1
L21_1 = "什么？你刚才说什么？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Wie bitte? Was hast du gerade gesagt?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Pardon ? Qu'est-ce que vous avez dit ?"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "COUNTERCASE_YUNA_NORMAL_4@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 30914
L21_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L22_1 = "L"
L21_1.m_Pos = L22_1
L22_1 = "……예!? 아, 아, 아니에요. 민초 협회 나쁜 놈들!!"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "……はい！？　あ、な、何でもないです。チョウミン協会、悪い人たちですね！"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Oh, i-it’s nothing. Those evil MC Society criminals!"
L21_1.m_Talk_ENG = L22_1
L22_1 = "……喔！沒，沒什麼。超博協會的壞蛋！！"
L21_1.m_Talk_TWN = L22_1
L22_1 = "โอ้ ฉัน-มันไม่มีอะไรเลย พวกอาชญากร สมาคม MC  ผู้ชั่วร้าย!"
L21_1.m_Talk_THA = L22_1
L22_1 = "Ồ, tôi-không có gì đâu. Những tên tội phạm của Hội MC độc ác!"
L21_1.m_Talk_VTN = L22_1
L22_1 = "……啊！？没、没、没什么。薄荷巧克力协会的这些坏蛋们！！"
L21_1.m_Talk_SCN = L22_1
L22_1 = "... Ich?! N-n-nichts. Der Minzschoko-Verein! Was für Schurken!!!"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Hein ? Euh non, r-rien. Bien fait pour ces criminels !"
L21_1.m_Talk_FRA = L22_1
