L25_1 = "YUMI_POLICE_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "……그래서 이 빈대떡 같은 게 범죄자도 홀릴 만큼 대단하단 말이야?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "……それでこの変わったチヂミみたいなものが犯罪者も魅了するほどのメニューってこと？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "So, this is the dish that even criminals couldn't resist?"
L24_1.m_Talk_ENG = L25_1
L25_1 = "……所以這個長得像綠豆煎餅的東西很厲害嗎？厲害到可以把犯罪組織唬得一愣一愣的。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "นี่คืออาหารจานที่แม้แต่อาชญากรยังอดใจไม่ไหวเหรอ?"
L24_1.m_Talk_THA = L25_1
L25_1 = "Vậy đây có phải món ăn mà ngay cả tội phạm cũng không thể cưỡng lại?"
L24_1.m_Talk_VTN = L25_1
L25_1 = "……所以，就是用这东西完美骗过了那些罪犯吗？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "... Dieser Schmarrn hier ist also derart toll, dass er sogar Kriminelle anlockt?"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Alors ces galettes sont si bonnes que même les criminels en raffolent... ?"
L24_1.m_Talk_FRA = L25_1
