L27_1 = "UNIT_HATE"
L26_1.m_Face = L27_1
L27_1 = "YUMI_POLICE_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "C"
L26_1.m_Crash = 30
L27_1 = "……으읍, 쓰다 못해 맵잖아. 대체 이런 걸 왜 먹는 거야."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "……ううっ。苦いどころか辛いわ。なんでこんなのを食べるわけ？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Urgh. It’s bitter... and spicy. What the heck is this?!"
L26_1.m_Talk_ENG = L27_1
L27_1 = "……噁，這也太辣了吧？到底誰會吃這種東西！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เอิร์ก มีรสขม...และเผ็ด นี่มันบ้าอะไรเนี่ย!"
L26_1.m_Talk_THA = L27_1
L27_1 = "Khẩn cấp. Nó đắng... và cay. Cái quái gì đây?!"
L26_1.m_Talk_VTN = L27_1
L27_1 = "……唔唔，又苦又辣。为什么要吃这种东西呢。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "... Mmpf, das ist ja nicht mehr bitter, sondern schon scharf. Warum zum Geier isst man so was?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Beurk ! C'est amer et épicé à la fois... Qui voudrait d'un truc pareil ?"
L26_1.m_Talk_FRA = L27_1
