L31_1 = "COUNTERCASE_YUNA_NORMAL_4@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 30914
L30_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_IDLE"
L31_1 = "SOYEONG_POLICE_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "R"
L30_1.m_Pos = L31_1
L31_1 = "어쨌든 민초 협회 검거에 유나 씨가 큰 기여를 해주셨기 때문에 경찰 본부 측에서 감사패가 나올 겁니다."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "とにかく、ユナさんはチョウミン協会の逮捕に大きく貢献してくださったので、\n警察本部から感謝状が贈られる予定です。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Well, since you helped us greatly with arresting the criminals, the police will reward you with a plaque of commendation."
L30_1.m_Talk_ENG = L31_1
L31_1 = "總之謝謝尤娜幫我們逮到超博協會這個犯罪組織，警方會頒發感謝狀給你。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เนื่องจากคุณช่วยเราอย่างมากในการจับกุมคนร้าย ตำรวจจะมอบโล่ประกาศเกียรติคุณให้คุณ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Chà, vì cô đã giúp chúng tôi rất nhiều trong việc bắt giữ tội phạm nên cảnh sát sẽ thưởng cho cô một tấm bảng khen ngợi."
L30_1.m_Talk_VTN = L31_1
L31_1 = "总之，因为在薄荷巧克力协会的行动中，尤娜小姐有巨大贡献，警察本部会特别发放感谢牌。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Jedenfalls hast du einen großen Beitrag geleistet zur Verhaftung des Minzschoko-Vereins. Dafür wird dir eine Dankesplakette des Polizei zukommen."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Quoi qu'il en soit, nous souhaiterions vous offrir une plaque pour vous remercier de votre aide. Sans vous, nous n'aurions jamais pu faire ce coup de filer."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "COUNTERCASE_YUNA_NORMAL_4@181#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 30914
L31_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_SURPRISE"
L31_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L32_1 = "L"
L31_1.m_Pos = L32_1
L31_1.m_Crash = 20
L32_1 = "네? 안 그러셔도 돼요!! 서, 선량한 시민으로서 당연한 일인 걸요!!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "えっ？　そんなの大丈夫です！！\nぜ、善良な市民として当たり前のことをしただけですから！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Oh, that won’t be necessary! It was my duty as a good citizen."
L31_1.m_Talk_ENG = L32_1
L32_1 = "蛤？不用啦！這是身為一位良好市民該做的事！！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "โอ้ นั่นไม่จำเป็นเลย! มันเป็นหน้าที่ของฉันในฐานะพลเมืองที่ดี"
L31_1.m_Talk_THA = L32_1
L32_1 = "Ồ, điều đó sẽ không cần thiết! Đó là nghĩa vụ của tôi với tư cách là một công dân tốt bụng."
L31_1.m_Talk_VTN = L32_1
L32_1 = "嗯？不用这样的！！作、作为遵纪守法的市民，这是我应该做的！！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Mir? Das ist nicht nötig! D-das war eine selbstverständliche Tat, da ich eine a-aufrechte Bürgerin bin!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "C'est gentil, mais ce n'est pas la peine ! J-je n'ai fait que mon devoir..."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
