L33_1.m_Pos = "C"
L33_1.m_Crash = 30
L34_1 = "기자들도 꽤 오겠죠?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "贈呈式には記者の方々も来るでしょうね。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "There will be reporters, too."
L33_1.m_Talk_ENG = L34_1
L34_1 = "應該會有很多記者來採訪你喔？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "จะมีนักข่าวด้วย"
L33_1.m_Talk_THA = L34_1
L34_1 = "Sẽ có cả phóng viên nữa."
L33_1.m_Talk_VTN = L34_1
L34_1 = "应该也会来很多记者吧？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Es werden recht viele Journalisten kommen, was?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Vraiment ? Cela devrait pourtant attirer les journalistes..."
L33_1.m_Talk_FRA = L34_1
