L35_1 = "COUNTERCASE_YUNA_NORMAL_4@184#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 30914
L34_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "UNIT_PRIDE"
L34_1.m_Face = L35_1
L35_1 = "SOYEONG_POLICE_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "용감한 카페 점원, 민초로 민초 잡다. 아마 카페 홍보에도 꽤 도움되지 않을까요?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "勇敢なカフェの店員、チョコミントでチョウミンを捕まえる。\nおそらく、カフェの宣伝にも繋がるのでは？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "A brave cafe employee catches criminals with mint chocolate. It will be great PR for your cafe."
L34_1.m_Talk_ENG = L35_1
L35_1 = "勇敢的咖啡廳店員，用薄荷巧克力逮到犯人！說不定可以替咖啡廳宣傳一波喔？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "พนักงานร้านกาแฟผู้กล้าหาญจับคนร้ายด้วยช็อกโกแลตมิ้นต์ มันจะเป็นประชาสัมพันธ์ที่ดีสำหรับร้านกาแฟของคุณ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Một nhân viên quán cà phê dũng cảm bắt tội phạm bằng sô cô la bạc hà. Nó sẽ là chiêu PR tuyệt vời cho quán cà phê của cô."
L34_1.m_Talk_VTN = L35_1
L35_1 = "勇敢的咖啡店店员，巧用薄荷巧克力抓捕罪犯。对店铺的宣传应该也有帮助哦？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Eine mutige Café-Angestellte, die den Minzschoko-Verein per Minzschoko schnappte. Das wäre ziemlich gute Werbung für euer Café, oder?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "« La serveuse d'un café aide la police à attraper des criminels ». Pas mal pour un coup de pub, non ?"
L34_1.m_Talk_FRA = L35_1
