L41_1 = "THEMA_BOSS_PAWN"
L40_1.m_StartBGMFileName = L41_1
L41_1 = "MAVERICK_NPC_NULL_NULL"
L40_1.m_CharStrID = L41_1
L41_1 = "……쳇! 아무리 생각해도 아까워. 민초 협회는 전부터 내가 노리고 있었다고!"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "……チッ！　悔しい。チョウミン協会は私が前から目をつけていたのに！"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Aww, what a shame. I’ve been after MC Society for a while now."
L40_1.m_Talk_ENG = L41_1
L41_1 = "……嘖！真可惜，超博協會原本是我的獵物欸！"
L40_1.m_Talk_TWN = L41_1
L41_1 = "แย่จังเลย ฉันติดตาม สมาคม MC  มาระยะหนึ่งแล้ว"
L40_1.m_Talk_THA = L41_1
L41_1 = "Ôi, thật đáng xấu hổ. Tôi đã theo đuổi MC Society được một thời gian rồi."
L40_1.m_Talk_VTN = L41_1
L41_1 = "……切！想想真是可惜。薄荷巧克力协会是我一直盯着来着！"
L40_1.m_Talk_SCN = L41_1
L41_1 = "... Hmpf! Ich finde es echt schade. Ich hatte den Minzschoko-Verein schon viel länger im Visier!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Quelle guigne ! Depuis le temps que je guettais l'association CM..."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "COUNTERCASE_YUNA_NORMAL_4@191#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 30914
L41_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "MAVERICK_NPC_NULL_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "이런 아날로그적인 방식으로 허를 찔리다니!! 카페 점원 주제에 꽤 머리가 좋잖아?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "こんなアナログなやり口にやられるとは！　カフェ店員のくせに頭が切れているじゃないか。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I didn’t expect such a classic sting would work on them! She’s pretty smart for a cafe server."
L41_1.m_Talk_ENG = L42_1
L42_1 = "竟然用這種傳統的方式逮到犯人！！那個咖啡廳店員腦筋不錯嘛？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ไม่คิดว่าการต่อยแบบคลาสสิกจะได้ผลกับพวกมัน! เธอค่อนข้างฉลาดสำหรับพนักงานเสิร์ฟร้านกาแฟ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tôi không ngờ rằng một cú chích cổ điển như vậy lại có tác dụng với họ! Người phục vụ quán cà phê khá thông minh đấy."
L41_1.m_Talk_VTN = L42_1
L42_1 = "竟然这样被人捷足先登！！没想到咖啡店的店员这么聪明。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Nie hätte ich erwartet, auf diese analoge Weise übertrumpft zu werden!!! Sie ist ganz schön schlau für eine Café-Mitarbeiterin!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Cette gamine a réussi à me doubler avec une méthode pareille ? Plutôt malin pour une serveuse..."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "COUNTERCASE_YUNA_NORMAL_4@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 30914
L42_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "ALBERT_NPC_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "그나저나 매버릭. 그래서 결국 민트 초코 오믈렛 먹어 봤어?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "それはそうとしてマーベリック、結局チョコミントオムレツは食べた？"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Hey, Maverick. Did you try the Mint Chocolate Omelet?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "不過麥伯利，結果你有吃到薄荷巧克力歐姆蛋嗎？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "เฮ้ มาเวอริก คุณลอง ไข่เจียวช็อคโกแลตมิ้นท์  หรือยัง?"
L42_1.m_Talk_THA = L43_1
L43_1 = "Này, Maverick. Anh đã thử món trứng tráng sôcôla bạc hà chưa?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "话说，麦伯利。你尝过那个薄荷巧克力煎蛋卷了吗？"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Übrigens, Maverick. Hast du das Minzschoko-Omelette nun probiert?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Au fait, Maverick. Tu l'as goûtée, cette omelette choco-menthe ?"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "COUNTERCASE_YUNA_NORMAL_4@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 30914
L43_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "MAVERICK_NPC_NULL_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "당연하지. 어제 꼬박 두 시간을 기다려서 먹고 왔다고."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "当然だろ。昨日2時間も待ち続けて食べてきたよ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Sure. I waited for two hours for that."
L43_1.m_Talk_ENG = L44_1
L44_1 = "當然有，我昨天可是足足等了二個小時才吃到欸！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "แน่นอน ฉันรอเป็นเวลาสองชั่วโมงเพื่อสิ่งนั้น"
L43_1.m_Talk_THA = L44_1
L44_1 = "Chắc chắn. Tôi đã đợi hai tiếng đồng hồ cho điều đó."
L43_1.m_Talk_VTN = L44_1
L44_1 = "当然了。昨天排队等了两个小时才吃到。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Klar doch. Nachdem ich gestern ganze zwei Stunden in der Schlange gestanden habe."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Évidemment ! J'ai fait la queue pendant deux heures rien que pour ça !"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
