L46_1 = "COUNTERCASE_YUNA_NORMAL_4@195#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 195
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 30914
L45_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "SYLVIA_DELTA_NICK_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "뭐야, 그 괴상한 요리는."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "なによ、その変な料理は？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "What’s the heck is that?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "這是什麼詭異的料理？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "นี่มันอะไรกันเนี่ย?"
L45_1.m_Talk_THA = L46_1
L46_1 = "Cái quái gì vậy?"
L45_1.m_Talk_VTN = L46_1
L46_1 = "什么啊，这种奇怪的料理。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Was das dieses absurde Gericht denn sein?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "C'est quoi ce nom ?"
L45_1.m_Talk_FRA = L46_1
