L47_1 = "COUNTERCASE_YUNA_NORMAL_4@196#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 196
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 30914
L46_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "SYLVIA_DELTA_NICK_NULL"
L46_1.m_CharStrID = L47_1
L47_1 = "어제 먹었던 아침이 올라 올 것 같은 이름인데?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "昨日の朝食まで吐き出しそうな名前だけど？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "It sounds like puke."
L46_1.m_Talk_ENG = L47_1
L47_1 = "光是聽到名字就有種反胃感？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เสียงเหมือนอ้วก"
L46_1.m_Talk_THA = L47_1
L47_1 = "Nghe có vẻ kì kì."
L46_1.m_Talk_VTN = L47_1
L47_1 = "光听名字，就差点让我把昨天吃过的东西都吐出来？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Bei dem Namen ist mir, als würde mein Frühstück von gestern in mir hochkommen."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Je crois que je vais vomir..."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "COUNTERCASE_YUNA_NORMAL_4@197#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 30914
L47_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "ALBERT_NPC_NULL_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "뭐라고? 그걸 여지껏 안 먹어봤다고?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "何だって？　まだ食べてないのか？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "What? You haven’t tried it yet?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "什麼？你竟然還沒吃過？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "อะไร คุณยังไม่ได้ลองมันหรือยัง?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Cái gì? Chưa thử nó à?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "什么？你还没尝过？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Wie bitte? Du hast es immer noch nicht probiert?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Quoi ? Tu n'as toujours pas goûté ?"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "COUNTERCASE_YUNA_NORMAL_4@198#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 198
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 30914
L48_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "ALBERT_NPC_NULL_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "아무리 인터넷이 좋아도 가끔은 밖에 나가서 바람도 쐬고 사람도 만나, 사이버 캣."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "いくらネット世界の居心地がいいとは言え、たまには外の風に当たって人とも会いなよ、サイバーキャット。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Cyber Cat, I know you’re in love with cyberspace, but sometimes you have to see real people and get some fresh air, you know?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "賽博貓，你偶爾也出去接觸一下世界，和人交流一下吧，不要整天待在網路世界裡。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ไซเบอร์แคท ฉันรู้ว่าคุณหลงรักไซเบอร์สเปซ แต่บางครั้งคุณต้องเจอคนจริงๆ และสูดอากาศบริสุทธิ์นะรู้ไหม?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Cyber Cat, tôi biết cô yêu thích không gian mạng, nhưng đôi khi phải gặp người thật và hít thở không khí trong lành chứ?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "就算再怎么喜欢网上冲浪，也要偶尔出去见见世面啊，赛博猫。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "So toll das Internet auch ist, solltest du ab und zu mal vor die Tür gehen und Leute treffen, Cyber Cat."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Internet c'est bien mais tu devrais sortir de temps en temps, Cyber Cat."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "COUNTERCASE_YUNA_NORMAL_4@199#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 199
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 30914
L49_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "SYLVIA_DELTA_NICK_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "시끄러워, 적어도 너희들한테 그런 소리 듣고 싶지 않으니까."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "うるさい。アンタたちには言われたくないわ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Shut up, I don’t want to hear it from you."
L49_1.m_Talk_ENG = L50_1
L50_1 = "關你什麼事，才輪不到你們來說我咧。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "หุบปาก ฉันไม่อยากได้ยินมันจากคุณ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Im đi, tôi không muốn nghe điều đó từ cậu."
L49_1.m_Talk_VTN = L50_1
L50_1 = "吵死了。完全不想听你们啰嗦。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Halt die Klappe. Von euch lasse ich mir das nicht sagen."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Tais-toi ! Et puis tu peux parler, je te signale..."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "COUNTERCASE_YUNA_NORMAL_4@200#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 200
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 30914
L50_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "ALBERT_NPC_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "아무튼 어땠어, 매버릭? 생각보다 맛있었지?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "それでどうだった、マーベリック？　案外美味しかったでしょ？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "So, how was it, Maverick? Pretty good, right?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "怎麼樣，麥伯利？有比想像中好吃嗎？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "แล้วเป็นยังไงบ้าง มาเวอริค? ค่อนข้างดีใช่มั้ย?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Vậy mọi chuyện thế nào, Maverick? Khá tốt phải không?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "总之，那东西比想象中好吃吗？麦伯利？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Wie fandest du es jedenfalls, Maverick? Besser als gedacht, oder?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Bon, et qu'est-ce que tu en as pensé, Maverick ? C'était bon ?"
L50_1.m_Talk_FRA = L51_1
