L2_1 = "COUNTERCASE_YUNA_NORMAL_4@201#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 201
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 30914
L1_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "MAVERICK_NPC_NULL_NULL"
L1_1.m_CharStrID = L2_1
L2_1 = "맞아, 처음에는 어떻게 이런 걸 먹나 싶었는데, 먹다보니 자꾸 생각나더라고."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "ああ、最初はなんじゃこりゃって思ったけど、クセになる味だった。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Yeah. It was horrible at first, but it got better and better for some reason."
L1_1.m_Talk_ENG = L2_1
L2_1 = "有，一開始我也覺得這種東西是要怎麼吃，結果吃下去後反而會想念呢。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ใช่ ในตอนแรกมันแย่มาก แต่ก็ดีขึ้นเรื่อยๆ ด้วยเหตุผลบางอย่าง"
L1_1.m_Talk_THA = L2_1
L2_1 = "Vâng. Lúc đầu nó thật kinh khủng, nhưng vì lý do nào đó nó ngày càng tốt hơn."
L1_1.m_Talk_VTN = L2_1
L2_1 = "嗯，刚开始其实在想这东西完全无法下咽，但尝过之后又有些念念不忘。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Ganz genau. Am Anfang war ich noch entsetzt, wie man das essen soll, aber dann macht es irgendwie süchtig."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Oh début j'étais un peu perplexe mais étrangement plus on en mange, moins on peut s'en passer !"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "COUNTERCASE_YUNA_NORMAL_4@202#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 202
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 30914
L2_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "ALBERT_NPC_NULL_NULL"
L2_1.m_CharStrID = L3_1
L3_1 = "후후, 역시 우리 같은 천재들은 시대를 앞서가는 입맛을 타고나는 법이지."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "ふふ、やはり私たちのように時代を先取りする天才は味覚も違うものだな。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Haha, I guess geniuses like us are ahead of our time, even in the field of dessert."
L2_1.m_Talk_ENG = L3_1
L3_1 = "呵呵，像我們這種天才，口味果然也是與眾不同。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ฮ่าๆ ฉันคิดว่าอัจฉริยะอย่างพวกเรายังล้ำหน้าอยู่นะ แม้แต่ในเรื่องของหวานก็ตาม"
L2_1.m_Talk_THA = L3_1
L3_1 = "Haha, tôi đoán những thiên tài như chúng ta đều đi trước thời đại, kể cả trong lĩnh vực tráng miệng."
L2_1.m_Talk_VTN = L3_1
L3_1 = "呼呼。果然只有像我们这样的天才，才能拥有远超时代的口味。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Hoho, Genies wie wir haben eben einen angeborenen Geschmack, der dem Zeitalter voraus ist."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Héhé. Le monde a décidément besoin de génies comme nous."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "COUNTERCASE_YUNA_NORMAL_4@203#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 203
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 30914
L3_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_4"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "MAVERICK_NPC_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "맞아, 그런 의미에서 카페 점원. 마녀 코스프레를 하고 있지만 틀림없이 일반인이 아니야."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "ああ、そういう意味であのカフェの店員。魔女のコスプレなんかしていたけど、\nきっと一般人じゃない。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Yeah. In that sense, I believe the witch-costumed girl at the cafe is not an ordinary person."
L3_1.m_Talk_ENG = L4_1
L4_1 = "沒錯，那個咖啡廳店員雖然打扮得像魔女，但我猜她應該不是普通的小老百姓。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ใช่. ในแง่นั้น ฉันเชื่อว่าสาวชุดแม่มดในร้านกาแฟไม่ใช่คนธรรมดา"
L3_1.m_Talk_THA = L4_1
L4_1 = "Vâng. Nói vậy, tôi tin cô gái mặc trang phục phù thủy ở quán cà phê không phải là người bình thường."
L3_1.m_Talk_VTN = L4_1
L4_1 = "没错。所以那个扮演魔女角色的咖啡店店员，一定也不是普通人。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Genau. In dem Sinne ist die Mitarbeiterin im Café ganz sicher keine gewöhnliche Person, auch wenn sie im Hexenkostüm daherkommt."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Exactement. Oh, et cette serveuse... Derrière ses airs de sorcière, ce n'est pas une fille ordinaire."
L3_1.m_Talk_FRA = L4_1
