L7_1.m_fTalkTime = 0.03
L8_1 = "時間があったら後で寄ってみようかな。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Maybe I’ll pay a visit next time."
L7_1.m_Talk_ENG = L8_1
L8_1 = "下次無聊的話就去看看吧？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "บางทีฉันอาจจะไปเยี่ยมครั้งต่อไป"
L7_1.m_Talk_THA = L8_1
L8_1 = "Có lẽ lần sau tôi sẽ ghé qua."
L7_1.m_Talk_VTN = L8_1
L8_1 = "下次有机会，就去一次吧？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Wollen wir später mal hin, wenn uns langweilig ist?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "J'y ferai tour quand j'aurai le temps."
